import type { TopicalExam } from './types'

function q(id: number, question: string, options: string[], correctAnswer: number, explanation: string) {
  return { id, question, options, correctAnswer, explanation }
}

export const TOPICAL_MACRO: TopicalExam = {
  label: 'AP Macroeconomics',
  slug: 'ap-macroeconomics',
  units: [
    {
      unitNumber: 1,
      title: 'Basic Economic Concepts',
      easy: [
        q(1, 'Scarcity is the fundamental economic problem because:', ['There are not enough workers in the economy.', 'Human wants are unlimited while resources are limited.', 'The government cannot produce everything citizens need.', 'Technology cannot advance fast enough.'], 1, 'Scarcity exists because human wants and needs are virtually unlimited, but the resources available to satisfy them (land, labor, capital, entrepreneurship) are finite. This requires societies to make choices about how to allocate resources.'),
        q(2, 'The opportunity cost of a decision is best defined as:', ['The monetary price of a good or service', 'The value of the next best alternative forgone when making a choice', 'The total cost of all alternatives given up', 'The difference between the price and the value of a good'], 1, 'Opportunity cost is the value of the best alternative sacrificed when a choice is made. It represents what you give up to get something, reflecting the true economic cost of any decision.'),
        q(3, 'A production possibilities curve (PPC) that is concave (bowed outward) from the origin illustrates which concept?', ['Constant opportunity costs', 'Increasing opportunity costs', 'Decreasing opportunity costs', 'Unlimited resources'], 1, 'A concave PPC shows increasing opportunity costs: as production of one good increases, progressively more of the other good must be sacrificed. This occurs because resources are not equally efficient in producing all goods.'),
        q(4, 'Which of the following would cause an outward shift of a country\'s production possibilities curve?', ['An increase in unemployment', 'A decrease in consumer spending', 'An improvement in technology', 'An increase in imports'], 2, 'An outward shift of the PPC represents economic growth—the ability to produce more of both goods. This results from increases in resources (more labor, capital) or improvements in technology that make existing resources more productive.'),
        q(5, 'In a market economy, the "what to produce" question is primarily determined by:', ['Government central planning agencies', 'Consumer preferences expressed through their spending decisions', 'International trade organizations', 'Random allocation of resources'], 1, 'In a market economy, consumer sovereignty drives production decisions. Firms produce goods that consumers are willing and able to buy. Consumer spending signals to producers what to make, how much to make, and at what price.'),
      ],
      medium: [
        q(6, 'Country A can produce either 100 units of wheat or 50 units of cloth. Country B can produce either 80 units of wheat or 60 units of cloth. Which statement about comparative advantage is correct?', ['Country A has a comparative advantage in both goods.', 'Country A has a comparative advantage in wheat and Country B has a comparative advantage in cloth.', 'Country B has a comparative advantage in wheat.', 'Neither country has a comparative advantage.'], 1, 'Country A\'s opportunity cost of 1 wheat = 0.5 cloth; Country B\'s opportunity cost of 1 wheat = 0.75 cloth. Country A has a lower opportunity cost for wheat (comparative advantage in wheat). Country B\'s opportunity cost of 1 cloth = 1.33 wheat vs. Country A\'s 2 wheat, so Country B has a comparative advantage in cloth.'),
        q(7, 'A point inside the production possibilities curve indicates:', ['The economy is producing at maximum efficiency.', 'The economy is producing below its potential, indicating unemployed or underutilized resources.', 'The economy has experienced economic growth.', 'The economy is producing an impossible combination of goods.'], 1, 'Points inside the PPC represent inefficiency—the economy is not using all available resources or is not using them in their most productive capacity. Unemployment, underemployed resources, or inefficient allocation would place the economy inside the curve.'),
        q(8, 'According to the circular flow model, which of the following represents a leakage from the spending stream?', ['Consumer spending on domestic goods', 'Saving by households', 'Government spending on infrastructure', 'Business investment in new equipment'], 1, 'In the circular flow model, leakages (withdrawals) reduce the flow of spending: saving, taxes, and imports remove money from the domestic spending stream. Injections (investment, government spending, exports) add to it. For macroeconomic equilibrium, total leakages must equal total injections.'),
        q(9, 'If a country specializes according to comparative advantage and engages in trade, which outcome is expected?', ['Only the exporting country benefits.', 'Both trading partners can consume beyond their individual production possibilities curves.', 'The country with absolute advantage in both goods loses from trade.', 'Total world output decreases.'], 1, 'When countries specialize in goods for which they have a comparative advantage and trade, total world output increases. Both countries can consume combinations of goods that lie beyond their individual PPCs, representing mutual gains from trade.'),
        q(10, 'Marginal analysis in economics involves:', ['Examining the total costs and benefits of a decision', 'Comparing the additional (incremental) costs and benefits of a decision to determine the optimal level of activity', 'Analyzing only fixed costs in decision-making', 'Ignoring opportunity costs when making decisions'], 1, 'Marginal analysis compares the additional (marginal) benefit of an action to its additional (marginal) cost. An economically rational decision-maker continues an activity as long as marginal benefit exceeds marginal cost, stopping where MB = MC.'),
      ],
      hard: [
        q(11, 'An economy is currently operating on its production possibilities curve. The government decides to invest heavily in education and infrastructure. Which short-run and long-run effects are most likely?', ['Short-run: movement along the PPC toward capital goods; Long-run: outward shift of the PPC', 'Short-run: outward shift of the PPC; Long-run: inward shift of the PPC', 'Short-run: no change; Long-run: no change', 'Short-run: the economy moves inside the PPC; Long-run: the PPC shifts inward'], 0, 'In the short run, investing in education and infrastructure requires diverting resources from current consumer goods production (moving along the PPC toward capital/investment goods). In the long run, these investments increase human capital and productive capacity, shifting the PPC outward—representing economic growth.'),
        q(12, 'Country X has an absolute advantage in producing both steel and textiles over Country Y. Under what conditions would trade still benefit both countries?', ['Trade can never benefit Country X because it is more efficient in both goods.', 'Trade benefits both countries as long as they have different opportunity costs (comparative advantages) for the two goods, regardless of absolute advantage.', 'Only if Country Y has a lower absolute cost in at least one good.', 'Only if both countries have identical opportunity costs.'], 1, 'The principle of comparative advantage shows that even when one country has an absolute advantage in all goods, trade benefits both parties if their opportunity costs differ. Each country specializes in the good with the lower opportunity cost, increasing total output and allowing both to consume more through trade.'),
        q(13, 'A PPC shifts outward for Good X but remains unchanged for Good Y. Which factor most likely caused this change?', ['A general increase in the labor force', 'A technological advancement specific to the production of Good X', 'Discovery of new natural resources usable in both industries', 'An increase in consumer demand for Good X'], 1, 'An asymmetric (pivotal) shift of the PPC—outward for one good only—occurs when a factor specifically increases productive capacity for that good. A technological improvement specific to Good X increases maximum X production without affecting Y production, rotating the PPC outward along the X axis.'),
        q(14, 'In the circular flow model, if planned saving exceeds planned investment, what macroeconomic outcome is predicted?', ['GDP will increase as savings fuel future growth.', 'GDP will decrease because total leakages exceed total injections, reducing aggregate spending below output levels.', 'GDP remains unchanged because saving and investment always balance.', 'Inflation will increase due to excess money supply.'], 1, 'When planned saving (a leakage) exceeds planned investment (an injection), total spending in the economy falls below total output. Inventories accumulate unexpectedly, firms reduce production, and GDP contracts until a new equilibrium is reached where saving equals investment at a lower income level (the paradox of thrift concept).'),
        q(15, 'Two countries with identical PPCs decide to specialize and trade. Would trade still be mutually beneficial?', ['Yes, because specialization always increases world output.', 'No, because identical PPCs mean identical opportunity costs, so there is no comparative advantage and no gains from specialization and trade.', 'Yes, but only if one country has more workers.', 'No, because identical PPCs mean one country has an absolute advantage.'], 1, 'If two countries have identical PPCs, they have identical opportunity costs for all goods. Since comparative advantage is based on differences in opportunity costs, identical PPCs mean no comparative advantage exists, and there would be no gains from specialization and trade between them.'),
      ],
    },
    {
      unitNumber: 2,
      title: 'Economic Indicators and the Business Cycle',
      easy: [
        q(16, 'Gross Domestic Product (GDP) measures:', ['The total value of all goods and services produced within a country\'s borders in a given time period', 'The total income of all citizens regardless of where they work', 'The total value of a country\'s exports', 'The total government spending in a year'], 0, 'GDP measures the total market value of all final goods and services produced within a country\'s borders during a specific time period (usually one year or one quarter). It is the most widely used measure of a nation\'s economic output.'),
        q(17, 'The unemployment rate is calculated as:', ['The number of unemployed divided by the total population', 'The number of unemployed divided by the labor force, multiplied by 100', 'The number of people not working divided by the total population', 'The number of job openings divided by the number of applicants'], 1, 'The unemployment rate = (Number of unemployed / Labor force) × 100. The labor force includes only those who are employed or actively seeking work, not the entire population. Discouraged workers, retirees, and students not seeking jobs are not in the labor force.'),
        q(18, 'Inflation is best defined as:', ['An increase in the price of a single good', 'A sustained increase in the general price level of goods and services in an economy', 'An increase in the money supply', 'A decrease in the purchasing power of foreign currencies'], 1, 'Inflation is a sustained, general increase in the overall price level, not just the price of one or a few goods. It reduces the purchasing power of money—each dollar buys fewer goods and services over time.'),
        q(19, 'Which phase of the business cycle is characterized by rising real GDP, falling unemployment, and increasing economic activity?', ['Recession', 'Expansion', 'Peak', 'Trough'], 1, 'An expansion (recovery) is the phase of the business cycle where real GDP grows, unemployment falls, consumer and business confidence increase, and overall economic activity increases. It occurs between a trough and a peak.'),
        q(20, 'Nominal GDP differs from real GDP in that nominal GDP:', ['Adjusts for inflation', 'Does not adjust for changes in the price level', 'Always understates the true level of output', 'Measures output using base-year prices'], 1, 'Nominal GDP measures output using current-year prices and does not adjust for inflation. Real GDP adjusts for price level changes by using constant (base-year) prices, providing a more accurate measure of actual changes in output over time.'),
      ],
      medium: [
        q(21, 'A worker who is unemployed because their skills do not match available job openings is experiencing which type of unemployment?', ['Cyclical unemployment', 'Structural unemployment', 'Frictional unemployment', 'Seasonal unemployment'], 1, 'Structural unemployment occurs when workers\' skills, locations, or characteristics don\'t match the requirements of available jobs. It results from technological change, shifts in the economy, or geographic mismatches and tends to be longer-lasting than frictional unemployment.'),
        q(22, 'The Consumer Price Index (CPI) is often criticized because it may overstate inflation due to:', ['Including too few goods in its basket', 'Not accounting for substitution bias, quality improvements, and new product introduction', 'Measuring wholesale rather than retail prices', 'Being updated too frequently'], 1, 'The CPI can overstate inflation because its fixed basket doesn\'t immediately account for consumers substituting cheaper alternatives (substitution bias), improvements in product quality (quality bias), or new products entering the market. These biases mean the CPI may overstate the true increase in the cost of living.'),
        q(23, 'If nominal GDP is $20 trillion and the GDP deflator is 125, real GDP is approximately:', ['$25 trillion', '$16 trillion', '$20 trillion', '$15 trillion'], 1, 'Real GDP = (Nominal GDP / GDP deflator) × 100 = ($20 trillion / 125) × 100 = $16 trillion. The GDP deflator above 100 indicates prices have risen above the base year level, so real GDP (adjusted for inflation) is less than nominal GDP.'),
        q(24, 'During a recession, which of the following combinations of economic indicators would most likely be observed?', ['Rising GDP, falling unemployment, rising inflation', 'Falling GDP, rising unemployment, falling or stable inflation', 'Rising GDP, rising unemployment, rising inflation', 'Falling GDP, falling unemployment, rising inflation'], 1, 'During a recession, real GDP declines for at least two consecutive quarters, firms lay off workers (rising unemployment), and weakening demand typically puts downward pressure on prices (falling or stable inflation). This combination reflects the contraction phase of the business cycle.'),
        q(25, 'The labor force participation rate has been declining in the United States. Which factor would NOT explain this trend?', ['An aging population with more retirees', 'Increased enrollment in higher education', 'Rising real wages attracting more workers', 'Discouraged workers leaving the labor force'], 2, 'Rising real wages would attract more workers into the labor force, increasing participation—the opposite of the trend. An aging population (more retirees), increased college enrollment (students not seeking work), and discouraged workers (who stop looking and exit the labor force) all reduce the participation rate.'),
      ],
      hard: [
        q(26, 'An economy has the following data: Consumer spending = $10T, Investment = $3T, Government spending = $4T, Exports = $2T, Imports = $3T. GDP equals:', ['$22 trillion', '$16 trillion', '$19 trillion', '$13 trillion'], 1, 'GDP = C + I + G + (X - M) = $10T + $3T + $4T + ($2T - $3T) = $10T + $3T + $4T - $1T = $16 trillion. Net exports are negative (trade deficit), which subtracts from GDP.'),
        q(27, 'The natural rate of unemployment includes which types of unemployment?', ['Only cyclical unemployment', 'Frictional and structural unemployment, but not cyclical unemployment', 'All types of unemployment including cyclical', 'Only frictional unemployment'], 1, 'The natural rate of unemployment (also called the non-accelerating inflation rate of unemployment, or NAIRU) includes frictional unemployment (workers between jobs) and structural unemployment (skills mismatch). It excludes cyclical unemployment, which is caused by economic downturns. The economy is at "full employment" when only natural unemployment exists.'),
        q(28, 'If real GDP grew by 3% and the population grew by 4% during the same year, which conclusion is most accurate?', ['The average standard of living improved.', 'The average standard of living declined because real GDP per capita fell.', 'Economic growth was sufficient to improve living standards.', 'The population decline offset GDP growth.'], 1, 'Real GDP per capita (GDP divided by population) is a better measure of average living standards than total GDP. If population grows faster (4%) than real GDP (3%), per capita GDP falls, meaning the average person\'s share of economic output decreased, suggesting a decline in average living standards.'),
        q(29, 'A country reports zero percent inflation but observes that housing costs rose 15% while electronics prices fell 20%. This scenario illustrates:', ['The absence of any price changes in the economy', 'That the overall price level can remain stable while individual sectors experience significant price increases and decreases that offset each other in aggregate measures', 'That the CPI is perfectly accurate', 'Deflation in the overall economy'], 1, 'Aggregate price indices like the CPI are weighted averages of many prices. Individual sectors can experience significant price changes in opposite directions that cancel out in the aggregate, producing a stable overall price level while individual consumers face very different inflation experiences depending on their spending patterns.'),
        q(30, 'An economist argues that GDP is a poor measure of economic well-being. Which combination of factors best supports this argument?', ['GDP is too difficult to calculate accurately.', 'GDP excludes non-market activities (household work, volunteer services), does not account for income distribution or inequality, ignores environmental degradation and resource depletion, and does not measure quality of life factors like leisure time and health.', 'GDP includes government spending, which should not count.', 'GDP does not measure nominal output.'], 1, 'GDP has significant limitations as a welfare measure: it counts market transactions but misses non-market production (childcare, household labor), treats pollution cleanup as positive output while ignoring environmental damage, doesn\'t reflect how income is distributed, excludes the underground economy, and doesn\'t capture quality of life indicators like health, education quality, leisure, or life satisfaction.'),
      ],
    },
    {
      unitNumber: 3,
      title: 'National Income and Price Determination',
      easy: [
        q(31, 'The aggregate demand (AD) curve slopes downward because of which effects?', ['The substitution effect and income effect only', 'The wealth effect, interest rate effect, and exchange rate effect', 'The law of diminishing returns', 'Government price controls'], 1, 'The AD curve slopes downward due to three effects of price level changes: the wealth effect (higher prices reduce real wealth and spending), the interest rate effect (higher prices increase money demand, raising interest rates and reducing investment), and the exchange rate effect (higher prices make domestic goods more expensive relative to foreign goods, reducing net exports).'),
        q(32, 'Which of the following would shift the aggregate demand curve to the right?', ['An increase in taxes', 'A decrease in government spending', 'An increase in consumer confidence leading to more spending', 'An increase in interest rates'], 2, 'An increase in consumer confidence increases consumption spending (C), shifting the AD curve rightward. Other rightward AD shifters include increased government spending (G), decreased taxes, increased investment (I), increased net exports (NX), and expansionary monetary policy.'),
        q(33, 'The short-run aggregate supply (SRAS) curve slopes upward because:', ['Higher price levels lead to more government spending.', 'As the price level rises with sticky input costs, firms find it profitable to increase output.', 'Workers demand higher wages immediately when prices rise.', 'Technology improves as prices increase.'], 1, 'The SRAS slopes upward because input prices (wages, contracts) are sticky in the short run. When the overall price level rises but input costs haven\'t adjusted, firms\' profit margins increase, incentivizing them to expand production.'),
        q(34, 'Long-run aggregate supply (LRAS) is vertical because in the long run:', ['Prices are permanently fixed', 'The economy\'s output is determined by its productive capacity (resources, technology, institutions) regardless of the price level', 'Government controls all production decisions', 'Aggregate demand determines the price level'], 1, 'The LRAS is vertical at the full-employment level of output because in the long run, all input prices fully adjust to changes in the price level. Output is determined by real factors—available resources, technology, and institutional efficiency—not by the price level.'),
        q(35, 'If the economy is in short-run equilibrium with real GDP below full-employment output, this situation is called a:', ['Inflationary gap', 'Recessionary gap (negative output gap)', 'Stagflation', 'Full-employment equilibrium'], 1, 'A recessionary gap (negative output gap) occurs when actual real GDP is below potential (full-employment) GDP. This means the economy has unemployed resources and output is below its productive capacity, typically accompanied by higher-than-natural unemployment.'),
      ],
      medium: [
        q(36, 'An adverse supply shock (such as a sudden increase in oil prices) would be shown in the AD-AS model as:', ['A rightward shift of the AD curve', 'A leftward shift of the SRAS curve, leading to higher prices and lower output (stagflation)', 'A rightward shift of the SRAS curve', 'A leftward shift of the AD curve'], 1, 'An adverse supply shock increases production costs for firms, shifting the SRAS curve leftward. This results in a higher price level (inflation) combined with lower real GDP and higher unemployment—a condition known as stagflation.'),
        q(37, 'The spending multiplier effect means that an initial change in spending causes a larger change in GDP because:', ['The government matches all private spending increases.', 'Each round of spending becomes someone else\'s income, who then spends a portion of it, creating successive rounds of spending that amplify the initial change.', 'Banks create money equal to the initial spending increase.', 'Prices decrease in response to increased spending.'], 1, 'The multiplier effect occurs because one person\'s spending becomes another\'s income. If the MPC is 0.8, an initial $100 increase in spending generates $80 in new spending, then $64, then $51.20, and so on. The total increase in GDP exceeds the initial spending change by a factor of 1/(1-MPC).'),
        q(38, 'If the marginal propensity to consume (MPC) is 0.75, the spending multiplier equals:', ['0.75', '3', '4', '7.5'], 2, 'The spending multiplier = 1 / (1 - MPC) = 1 / (1 - 0.75) = 1 / 0.25 = 4. This means each dollar of new autonomous spending will ultimately increase GDP by $4 through the multiplier process.'),
        q(39, 'In the short run, a decrease in aggregate demand (AD shifts left) in the AD-AS model results in:', ['Higher price level and higher real GDP', 'Lower price level and lower real GDP', 'Higher price level and lower real GDP', 'Lower price level and higher real GDP'], 1, 'When AD decreases (shifts left), the new equilibrium occurs at a lower price level and lower real GDP. This represents a recession with declining output, rising unemployment, and deflationary or disinflationary pressure.'),
        q(40, 'Self-correction in the long run occurs when a recessionary gap causes:', ['The government to automatically increase spending.', 'Wages and other input prices to eventually fall due to high unemployment, shifting SRAS rightward until the economy returns to full employment.', 'The AD curve to automatically shift rightward.', 'Technology to improve, shifting LRAS rightward.'], 1, 'In a recessionary gap, high unemployment puts downward pressure on wages and input prices. Over time, lower input costs shift the SRAS rightward, moving the economy back toward full employment at a lower price level. This self-correction process may be slow, which is why some economists advocate for active stabilization policy.'),
      ],
      hard: [
        q(41, 'An economy is at full employment when the government simultaneously increases spending by $100 billion and raises taxes by $100 billion. According to the balanced budget multiplier, what is the net effect on GDP?', ['GDP increases by $400 billion.', 'GDP increases by $100 billion because the balanced budget multiplier equals 1.', 'GDP remains unchanged because the spending increase and tax increase cancel out.', 'GDP decreases by $100 billion.'], 1, 'The balanced budget multiplier equals 1. Government spending has a multiplier of 1/(1-MPC), while taxes have a multiplier of -MPC/(1-MPC). Combined: 1/(1-MPC) + [-MPC/(1-MPC)] = (1-MPC)/(1-MPC) = 1. Equal increases in spending and taxes increase GDP by exactly the amount of the spending/tax change.'),
        q(42, 'An economy experiencing stagflation faces a policy dilemma because:', ['Both fiscal and monetary policy can easily address stagflation.', 'Expansionary policy to reduce unemployment would worsen inflation, while contractionary policy to fight inflation would worsen unemployment—neither standard demand-side policy addresses both problems simultaneously.', 'Stagflation always resolves itself quickly through self-correction.', 'Stagflation only occurs in command economies.'], 1, 'Stagflation (simultaneous high inflation and high unemployment caused by a supply shock) creates a policy dilemma because demand-side tools work in opposite directions: expansionary policy fights unemployment but worsens inflation; contractionary policy fights inflation but worsens unemployment. Supply-side policies are needed to address the root cause.'),
        q(43, 'If the government cuts taxes by $50 billion and the MPC is 0.8, the maximum potential increase in GDP through the tax multiplier is:', ['$250 billion', '$200 billion', '$50 billion', '$400 billion'], 1, 'The tax multiplier = -MPC / (1 - MPC) = -0.8 / 0.2 = -4. A tax cut of $50 billion increases GDP by $50 billion × 4 = $200 billion. Note the tax multiplier is smaller in absolute value than the spending multiplier (which would be 5) because households save a portion of the tax cut.'),
        q(44, 'In the AD-AS model, if both AD and SRAS shift rightward simultaneously, which outcome is certain and which is ambiguous?', ['Both real GDP and the price level will definitely increase.', 'Real GDP will definitely increase, but the effect on the price level is ambiguous (depends on the relative magnitude of the shifts).', 'The price level will definitely increase, but the effect on real GDP is ambiguous.', 'Both real GDP and the price level changes are ambiguous.'], 1, 'When AD shifts right (increasing both output and prices) and SRAS shifts right (increasing output but decreasing prices), the output effects reinforce each other (GDP definitely increases). However, the price effects oppose each other (AD increases prices, SRAS decreases them), so the net effect on the price level depends on which shift is larger—making it ambiguous.'),
        q(45, 'A Keynesian economist and a classical economist disagree about the appropriate response to a recession. Which characterizes their positions?', ['Both agree that the government should not intervene.', 'The Keynesian argues for active fiscal and monetary policy to boost AD because wages and prices are sticky downward, making self-correction slow and costly; the classical economist argues the economy will self-correct as flexible wages and prices adjust, and government intervention may cause crowding out or inflation.', 'The classical economist favors more government intervention than the Keynesian.', 'Both favor supply-side tax cuts exclusively.'], 1, 'The core Keynesian-classical debate centers on wage/price flexibility and the speed of self-correction. Keynesians argue sticky wages and prices make recessions prolonged and costly, justifying government intervention. Classical economists believe wages and prices adjust quickly, the economy self-corrects to full employment, and government intervention creates distortions (crowding out, inflation expectations) that may worsen outcomes.'),
      ],
    },
    {
      unitNumber: 4,
      title: 'Financial Sector',
      easy: [
        q(46, 'The Federal Reserve (Fed) serves as the central bank of the United States. Its primary function is to:', ['Collect taxes and manage the federal budget', 'Conduct monetary policy, regulate banks, and maintain financial system stability', 'Set fiscal policy including government spending levels', 'Manage the Social Security trust fund'], 1, 'The Federal Reserve conducts monetary policy (controlling the money supply and interest rates), supervises and regulates banks, maintains financial system stability, and provides financial services to the government and financial institutions. It does not set fiscal policy.'),
        q(47, 'The money supply (M1) includes which components?', ['Savings accounts and certificates of deposit', 'Currency in circulation, demand deposits (checking accounts), and other checkable deposits', 'Only physical currency (coins and paper money)', 'Government bonds and Treasury securities'], 1, 'M1 is the most liquid measure of money supply and includes currency in circulation (coins and paper money held by the public), demand deposits (checking accounts), traveler\'s checks, and other checkable deposits. These are assets that can be immediately used as a medium of exchange.'),
        q(48, 'When the Fed wants to stimulate the economy, it typically:', ['Raises the federal funds rate', 'Lowers the federal funds rate to encourage borrowing and spending', 'Increases the reserve requirement', 'Sells government bonds on the open market'], 1, 'To stimulate the economy (expansionary monetary policy), the Fed lowers the federal funds rate, making borrowing cheaper for banks, businesses, and consumers. This encourages increased borrowing, investment, and spending, boosting aggregate demand.'),
        q(49, 'The quantity theory of money is expressed by the equation MV = PQ. In this equation, V represents:', ['The value of money', 'The velocity of money—the average number of times a dollar is spent in a year', 'The volume of transactions', 'The variability of interest rates'], 1, 'The velocity of money (V) measures how many times the average dollar is spent on final goods and services in a year. In the equation MV = PQ (or PY), M is money supply, V is velocity, P is price level, and Q (or Y) is real output.'),
        q(50, 'Banks create money through the process of:', ['Printing currency', 'Fractional reserve banking—lending out a portion of deposits while keeping a fraction in reserve', 'Collecting taxes on behalf of the government', 'Exchanging foreign currencies'], 1, 'Through fractional reserve banking, banks keep only a fraction of deposits as reserves and lend the rest. When loans are deposited in other banks, those banks can lend a fraction of the new deposits, creating a chain of deposit creation that multiplies the initial deposit into a larger money supply.'),
      ],
      medium: [
        q(51, 'If the reserve requirement is 10%, the maximum money multiplier is:', ['10', '0.10', '100', '1'], 0, 'The simple money multiplier = 1 / reserve requirement = 1 / 0.10 = 10. This means each dollar of new reserves can potentially support up to $10 in new deposits through the lending process. In practice, the actual multiplier is lower due to excess reserves and cash holdings.'),
        q(52, 'Open market operations are the Fed\'s most frequently used monetary policy tool. When the Fed buys government bonds:', ['The money supply decreases and interest rates rise.', 'The money supply increases and interest rates fall because banks have more reserves to lend.', 'The money supply is unaffected.', 'The federal budget deficit decreases.'], 1, 'When the Fed buys government bonds, it pays with newly created reserves, injecting money into the banking system. Banks with more reserves can make more loans, increasing the money supply. Greater supply of loanable funds pushes interest rates down, stimulating borrowing and economic activity.'),
        q(53, 'The Fisher equation (nominal interest rate = real interest rate + expected inflation) implies that if expected inflation increases while the real interest rate remains constant:', ['Nominal interest rates will decrease.', 'Nominal interest rates will increase by the same amount as the increase in expected inflation.', 'Nominal interest rates will remain unchanged.', 'Real interest rates will increase.'], 1, 'The Fisher equation shows that nominal interest rates incorporate inflation expectations. If expected inflation rises by 2 percentage points and the real interest rate is unchanged, lenders will demand 2 percentage points more in nominal interest to maintain their real return, increasing nominal rates accordingly.'),
        q(54, 'An increase in the money supply shifts the money supply curve to the right in the money market. If money demand is unchanged, this leads to:', ['Higher interest rates and decreased investment', 'Lower interest rates, which stimulates investment and increases aggregate demand', 'Higher interest rates and increased saving', 'No change in interest rates or economic activity'], 1, 'When money supply increases (shifts right) with unchanged money demand, there is a surplus of money at the current interest rate. People use excess money to buy bonds, pushing bond prices up and interest rates down. Lower interest rates stimulate investment spending and increase aggregate demand.'),
        q(55, 'Demand-pull inflation differs from cost-push inflation in that demand-pull inflation:', ['Causes unemployment to rise simultaneously', 'Is caused by increases in aggregate demand that push prices up when the economy is at or near full employment', 'Is caused by increases in production costs that shift SRAS leftward', 'Always results in a recessionary gap'], 1, 'Demand-pull inflation occurs when aggregate demand increases beyond the economy\'s productive capacity (AD shifts right at or beyond full employment), pulling prices up. Cost-push inflation results from increased production costs (SRAS shifts left), pushing prices up while simultaneously reducing output.'),
      ],
      hard: [
        q(56, 'The Fed lowers the federal funds rate from 5% to 2%. Trace the complete transmission mechanism through which this affects GDP.', ['Lower fed funds rate → decreased bank lending → lower consumption → lower GDP', 'Lower fed funds rate → increased bank reserves → more lending → lower interest rates for businesses and consumers → increased investment and consumption → rightward shift of AD → higher GDP and potentially higher price level', 'Lower fed funds rate → higher exchange rate → increased net exports → higher GDP', 'Lower fed funds rate → no economic effect because monetary policy is ineffective'], 1, 'The monetary transmission mechanism: The Fed lowers the federal funds rate, reducing the cost of interbank borrowing. Banks lower lending rates for businesses and consumers. Cheaper credit increases investment spending (I) and consumer purchases of durable goods. Increased I and C shift AD rightward, increasing real GDP and potentially the price level. Additionally, lower rates may weaken the dollar, boosting net exports.'),
        q(57, 'A liquidity trap occurs when:', ['Banks have too much liquidity and cannot find borrowers.', 'Nominal interest rates are near zero, making conventional monetary policy ineffective because the Fed cannot push rates significantly lower to stimulate borrowing and spending.', 'The money supply cannot be increased by the central bank.', 'Inflation is extremely high and people hoard cash.'], 1, 'A liquidity trap occurs at or near the zero lower bound of nominal interest rates. With rates near zero, additional money supply increases cannot lower rates further. People become indifferent between holding money and bonds (both yield nearly zero), so monetary expansion is "trapped" in cash holdings rather than stimulating spending. This situation may require unconventional monetary policy or fiscal policy.'),
        q(58, 'If the required reserve ratio is 20% and a bank receives a new deposit of $10,000, the maximum amount this bank can lend is $8,000. However, the maximum total money creation in the banking system from this deposit is:', ['$8,000', '$50,000', '$10,000', '$40,000'], 1, 'The individual bank can lend $8,000 (= $10,000 × (1 - 0.20)). But through the money multiplier process across the banking system: total money creation = $10,000 × (1/0.20) = $50,000. This includes the original $10,000 deposit. The change in deposits (new money created beyond the original) would be $50,000 total or $40,000 new money beyond the original deposit.'),
        q(59, 'An economy faces a situation where the real interest rate is negative (nominal rate < inflation rate). Which of the following is a consequence?', ['Savers benefit because their purchasing power increases.', 'Borrowers benefit because they repay loans with money that has less purchasing power than when borrowed, effectively receiving a subsidy for borrowing.', 'The money supply automatically contracts.', 'Banks stop all lending activities.'], 1, 'Negative real interest rates mean the inflation rate exceeds the nominal interest rate. Borrowers benefit because the real burden of their debt decreases—they repay with dollars that buy less than when they borrowed. Savers lose purchasing power because the interest they earn doesn\'t compensate for inflation. This incentivizes borrowing and spending over saving.'),
        q(60, 'The concept of the "loanable funds market" differs from the "money market" in that:', ['They are identical models with different names.', 'The loanable funds market shows the supply and demand for saving and investment, determining the real interest rate, while the money market shows the supply and demand for money, determining the nominal interest rate.', 'The money market determines fiscal policy while the loanable funds market determines monetary policy.', 'The loanable funds market only exists in developing economies.'], 1, 'The loanable funds market shows the interaction of saving (supply) and investment demand, determining the real interest rate. Changes in saving behavior or investment demand shift these curves. The money market shows the supply of money (controlled by the Fed) and demand for money (determined by income and the interest rate), determining the nominal interest rate. Both models are used in AP Macroeconomics but focus on different aspects of the financial sector.'),
      ],
    },
    {
      unitNumber: 5,
      title: 'Long-Run Consequences of Stabilization Policies',
      easy: [
        q(61, 'The Phillips curve illustrates the short-run trade-off between:', ['GDP and government spending', 'Inflation and unemployment', 'Interest rates and investment', 'Saving and consumption'], 1, 'The short-run Phillips curve shows an inverse relationship between inflation and unemployment: when unemployment falls (economy heats up), inflation tends to rise, and vice versa. This trade-off reflects the short-run AD-AS relationship.'),
        q(62, 'Crowding out occurs when:', ['Government spending leads to lower taxes', 'Increased government borrowing raises interest rates, reducing private investment', 'Government spending decreases aggregate demand', 'Private investment increases due to government spending'], 1, 'Crowding out occurs when government borrowing to finance deficit spending competes with private borrowers for loanable funds. This increased demand for loanable funds raises interest rates, which discourages (crowds out) some private investment, partially offsetting the stimulative effect of government spending.'),
        q(63, 'Fiscal policy refers to the government\'s use of which tools to influence the economy?', ['Interest rates and the money supply', 'Government spending and taxation', 'Exchange rates and trade barriers', 'Reserve requirements and open market operations'], 1, 'Fiscal policy involves the government adjusting its spending levels and tax rates to influence economic activity. Expansionary fiscal policy (increased spending or tax cuts) stimulates AD, while contractionary fiscal policy (reduced spending or tax increases) reduces AD.'),
        q(64, 'A government budget deficit occurs when:', ['Government revenue exceeds spending', 'Government spending exceeds revenue in a given fiscal year', 'The national debt decreases', 'Exports exceed imports'], 1, 'A budget deficit occurs when government expenditures exceed government revenues (primarily tax collections) during a fiscal year. The deficit must be financed by borrowing, which adds to the national debt.'),
        q(65, 'Automatic stabilizers help moderate the business cycle because they:', ['Require legislative action to take effect', 'Automatically increase government spending or reduce taxes during recessions without new legislation', 'Are controlled by the Federal Reserve', 'Only operate during periods of economic expansion'], 1, 'Automatic stabilizers (progressive income taxes, unemployment insurance, welfare programs) automatically adjust with economic conditions without requiring new legislation. During recessions, tax revenues fall and transfer payments rise, injecting spending into the economy. During expansions, taxes rise and transfers fall, cooling the economy.'),
      ],
      medium: [
        q(66, 'According to the long-run Phillips curve, there is no trade-off between inflation and unemployment because:', ['Inflation cannot occur in the long run.', 'In the long run, the economy returns to the natural rate of unemployment regardless of the inflation rate, as workers and firms adjust their expectations.', 'Government policy always prevents unemployment.', 'Wages are permanently sticky in the long run.'], 1, 'The long-run Phillips curve is vertical at the natural rate of unemployment. In the long run, workers and firms adjust their inflation expectations to match actual inflation. When expected inflation catches up to actual inflation, there is no "surprise" inflation to temporarily reduce unemployment, so the economy returns to the natural rate regardless of the inflation level.'),
        q(67, 'Expansionary fiscal policy financed by government borrowing can lead to crowding out. In the loanable funds market, this is shown as:', ['A leftward shift of the supply of loanable funds', 'A rightward shift of the demand for loanable funds, raising the real interest rate and reducing private investment', 'A rightward shift of the supply of loanable funds', 'No change in the loanable funds market'], 1, 'Government borrowing to finance deficit spending increases the demand for loanable funds (shifts right). With an unchanged supply, the real interest rate rises. Higher interest rates make some private investment projects unprofitable, reducing private investment—this is the crowding-out effect.'),
        q(68, 'Supply-side economists argue that tax cuts can increase long-run economic growth by:', ['Increasing government spending through higher tax revenue', 'Increasing incentives to work, save, and invest, thereby expanding productive capacity and shifting LRAS rightward', 'Directly increasing the money supply', 'Reducing imports and increasing net exports'], 1, 'Supply-side economics emphasizes that lower marginal tax rates increase after-tax returns to working, saving, and investing. This increases labor supply, saving (funding investment), and capital formation, expanding the economy\'s productive capacity and shifting LRAS rightward, promoting long-run growth.'),
        q(69, 'The distinction between discretionary fiscal policy and automatic stabilizers is that:', ['Discretionary policy is more effective than automatic stabilizers.', 'Discretionary fiscal policy requires deliberate legislative action, while automatic stabilizers take effect without new legislation as economic conditions change.', 'Automatic stabilizers require Congressional approval for each use.', 'Only automatic stabilizers affect aggregate demand.'], 1, 'Discretionary fiscal policy involves intentional changes in government spending or tax policy through legislation (e.g., stimulus packages, tax reform bills). Automatic stabilizers are built into the existing fiscal structure and activate automatically—tax collections naturally fall in recessions and transfer payments naturally increase, without requiring new laws.'),
        q(70, 'If the government runs persistent budget deficits, the national debt will increase. Which long-run concern is most directly associated with rising national debt?', ['Immediate hyperinflation', 'Potential crowding out of private investment as government borrowing consumes a larger share of available savings, potentially reducing long-run economic growth', 'Automatic elimination of all government programs', 'Immediate default on all government obligations'], 1, 'Persistent deficits increase the national debt, meaning the government competes with private borrowers for an increasing share of available savings. This can crowd out private investment over time, reducing capital formation and potentially slowing long-run economic growth. Additionally, rising interest payments on the debt consume an increasing share of the federal budget.'),
      ],
      hard: [
        q(71, 'The expectations-augmented Phillips curve suggests that if the central bank attempts to maintain unemployment below the natural rate permanently, the result will be:', ['A stable, lower unemployment rate with moderate inflation.', 'Accelerating inflation as workers continuously revise their inflation expectations upward, requiring ever-higher inflation to maintain below-natural unemployment.', 'Deflation combined with lower unemployment.', 'No change in either inflation or unemployment.'], 1, 'When unemployment is held below the natural rate, actual inflation exceeds expected inflation. Workers eventually adjust expectations upward, shifting the short-run Phillips curve up. To maintain low unemployment, authorities must generate even higher inflation to surprise workers again. This creates an accelerating inflation spiral, demonstrating that below-natural unemployment is unsustainable without ever-increasing inflation.'),
        q(72, 'A government implements a large fiscal stimulus during a recession, financed by borrowing. If the economy is in a liquidity trap, the crowding-out effect is likely to be:', ['Very large, completely offsetting the stimulus', 'Minimal, because interest rates are already near zero and cannot be pushed much higher by government borrowing, so private investment is not significantly displaced', 'Exactly equal to the stimulus', 'Impossible to determine under any circumstances'], 1, 'In a liquidity trap (interest rates near zero), there is excess saving and weak private investment demand. Government borrowing absorbs excess saving without significantly raising interest rates because the economy has abundant idle saving. With rates already near zero and investment weak, additional government borrowing doesn\'t crowd out private investment significantly, making fiscal policy more effective.'),
        q(73, 'The Laffer Curve illustrates that beyond a certain point, higher tax rates actually decrease tax revenue. This concept is most relevant when:', ['Tax rates are very low and near zero.', 'Tax rates are extremely high—so high that they significantly reduce the tax base by discouraging work, investment, and economic activity, causing revenue to decline.', 'The economy is in a severe recession.', 'The government is running a budget surplus.'], 1, 'The Laffer Curve shows tax revenue as a function of tax rates, peaking at some optimal rate. At very high rates, the disincentive effects dominate: people work less, invest less, engage in tax avoidance/evasion, and economic activity contracts, shrinking the tax base enough that total revenue falls. Tax cuts from very high rates could theoretically increase revenue.'),
        q(74, 'Time lags in fiscal policy implementation include recognition lag, decision lag, and implementation lag. Which scenario best illustrates how these lags can make fiscal policy destabilizing?', ['The government implements policy instantly and the economy responds immediately.', 'By the time contractionary fiscal policy enacted during an expansion takes full effect, the economy has already entered a recession, making the contractionary policy procyclical and worsening the downturn.', 'Time lags ensure fiscal policy is always perfectly timed.', 'Time lags only affect monetary policy, not fiscal policy.'], 1, 'Fiscal policy faces significant time lags: recognizing an economic problem (data delays), making policy decisions (legislative process), and implementing the policy (spending takes time to flow through the economy). If these lags total 12-18 months, a policy designed for current conditions may take effect when conditions have reversed, potentially destabilizing the economy by being procyclical.'),
        q(75, 'A country with high national debt faces a "debt spiral" risk when:', ['Its GDP growth rate consistently exceeds the interest rate on its debt.', 'The interest rate on its debt exceeds its GDP growth rate, causing the debt-to-GDP ratio to grow automatically even without new primary deficits, requiring ever-larger borrowing to service existing debt.', 'The country has a balanced budget.', 'The country prints money to pay all its debts.'], 1, 'A debt spiral occurs when the interest rate on government debt (r) exceeds the GDP growth rate (g). In this situation, the debt-to-GDP ratio grows automatically because interest payments accumulate faster than the economy grows. The government must borrow more just to pay interest, further increasing debt, which can lead to rising interest rates and an unsustainable trajectory.'),
      ],
    },
    {
      unitNumber: 6,
      title: 'Open Economy—International Trade and Finance',
      easy: [
        q(76, 'A tariff is a tax imposed on:', ['Domestic goods sold within a country', 'Imported goods entering a country', 'Exported goods leaving a country', 'All goods regardless of origin'], 1, 'A tariff is a tax levied on imported goods, increasing their price in the domestic market. Tariffs protect domestic producers from foreign competition but raise prices for domestic consumers and can provoke retaliatory trade barriers from trading partners.'),
        q(77, 'The balance of trade is the difference between a country\'s:', ['GDP and GNP', 'Exports and imports of goods and services', 'Government revenue and spending', 'Saving and investment'], 1, 'The balance of trade (trade balance) is the difference between the value of a country\'s exports and imports. A trade surplus occurs when exports exceed imports; a trade deficit occurs when imports exceed exports.'),
        q(78, 'In a flexible (floating) exchange rate system, the value of a currency is determined by:', ['Government decree', 'Supply and demand for that currency in the foreign exchange market', 'International agreements between central banks', 'The amount of gold reserves a country holds'], 1, 'In a floating exchange rate system, currency values are determined by market forces of supply and demand in the foreign exchange market. Factors affecting supply and demand include trade flows, capital flows, interest rate differentials, inflation rates, and market expectations.'),
        q(79, 'If the U.S. dollar appreciates relative to the euro, which effect is most likely?', ['U.S. exports to Europe become cheaper for Europeans.', 'U.S. exports to Europe become more expensive for Europeans, reducing U.S. export competitiveness.', 'European goods become more expensive for Americans.', 'There is no effect on trade between the U.S. and Europe.'], 1, 'Dollar appreciation means each dollar buys more euros. U.S. goods become more expensive for Europeans (they need more euros to buy the same dollar-priced goods), reducing U.S. export competitiveness. Conversely, European goods become cheaper for Americans, increasing U.S. imports from Europe.'),
        q(80, 'Which of the following is recorded in the capital (financial) account of the balance of payments?', ['Exports of manufactured goods', 'Tourism spending by foreign visitors', 'Foreign purchase of U.S. Treasury bonds', 'U.S. imports of petroleum'], 2, 'The capital (financial) account records international flows of financial assets: foreign investment in domestic stocks, bonds, and real estate (capital inflows), and domestic investment in foreign assets (capital outflows). A foreign purchase of U.S. Treasury bonds is a capital inflow recorded in the financial account.'),
      ],
      medium: [
        q(81, 'A country has a current account deficit. In the balance of payments, this must be offset by:', ['A current account surplus in the following year', 'A capital (financial) account surplus, meaning net capital inflows from abroad', 'An increase in the country\'s GDP', 'A decrease in the country\'s money supply'], 1, 'The balance of payments must balance: the current account + capital (financial) account = 0 (approximately). A current account deficit (importing more than exporting) must be financed by a capital account surplus—net capital inflows from foreign investment, lending, or asset purchases.'),
        q(82, 'If the U.S. Federal Reserve raises interest rates while other countries\' central banks keep rates unchanged, the most likely effect on the U.S. dollar is:', ['Depreciation, as higher rates discourage investment', 'Appreciation, as higher rates attract foreign capital seeking higher returns, increasing demand for dollars', 'No change, because exchange rates are unaffected by interest rates', 'Depreciation due to reduced consumer spending'], 1, 'Higher U.S. interest rates attract foreign investors seeking higher returns on dollar-denominated assets. This increases demand for U.S. dollars in the foreign exchange market, causing the dollar to appreciate relative to other currencies.'),
        q(83, 'A quota on imported steel differs from a tariff on imported steel in that a quota:', ['Generates tax revenue for the government', 'Directly limits the quantity of steel that can be imported, while a tariff raises the price but does not set a quantity limit', 'Is always less restrictive than a tariff', 'Reduces the domestic price of steel'], 1, 'A quota sets a maximum physical quantity of imports allowed, while a tariff raises the price through taxation. Both protect domestic producers and raise domestic prices, but a tariff generates government revenue while a quota does not (the price difference accrues to importers or foreign producers as "quota rents").'),
        q(84, 'If Japan\'s inflation rate is significantly higher than the U.S. inflation rate, the Japanese yen is likely to:', ['Appreciate against the dollar', 'Depreciate against the dollar, as Japanese goods become relatively more expensive, reducing demand for yen', 'Remain unchanged against the dollar', 'Appreciate because higher inflation indicates a stronger economy'], 1, 'Higher inflation in Japan makes Japanese goods relatively more expensive compared to U.S. goods. This reduces demand for Japanese exports (reducing demand for yen) and increases Japanese demand for cheaper U.S. imports (increasing supply of yen). Both effects cause the yen to depreciate.'),
        q(85, 'The concept of "twin deficits" refers to the relationship between:', ['Trade deficit and unemployment', 'A government budget deficit and a current account (trade) deficit, where government borrowing can contribute to a trade imbalance', 'Two consecutive years of GDP decline', 'Deficits in both the money market and loanable funds market'], 1, 'The twin deficits hypothesis suggests that government budget deficits contribute to current account deficits. Budget deficits reduce national saving, which can lead to higher interest rates and capital inflows (financial account surplus). The financial account surplus necessarily implies a current account deficit, linking the two deficits.'),
      ],
      hard: [
        q(86, 'A country devalues its currency (in a fixed exchange rate system) to improve its trade balance. Using the J-curve effect, describe the expected short-run and long-run outcomes.', ['Trade balance improves immediately and remains improved.', 'The trade balance initially worsens (because existing import contracts are more expensive in domestic currency) before improving as export volumes increase and import volumes decrease in response to the new exchange rate.', 'The trade balance worsens permanently.', 'Devaluation has no effect on the trade balance.'], 1, 'The J-curve effect shows that devaluation initially worsens the trade balance because imports immediately become more expensive (existing contracts and inelastic demand in the short run), while exports take time to increase (contracts, production capacity adjustments). Over time, as quantities adjust, exports increase and imports decrease, improving the trade balance—tracing a J-shaped path.'),
        q(87, 'In the loanable funds market for an open economy, if a country removes restrictions on foreign capital inflows, the most likely effect is:', ['The supply of loanable funds decreases and the real interest rate rises.', 'The supply of loanable funds increases as foreign saving enters the domestic market, lowering the real interest rate and increasing domestic investment.', 'There is no effect because foreign capital cannot enter domestic loanable funds markets.', 'The demand for loanable funds decreases.'], 1, 'Removing capital flow restrictions allows foreign saving to supplement domestic saving in the loanable funds market. This increases the supply of loanable funds (shifts right), lowering the domestic real interest rate and enabling more domestic investment. However, this also creates a financial account surplus and corresponding current account deficit.'),
        q(88, 'An expansionary monetary policy in a small open economy with flexible exchange rates will affect net exports through which channel?', ['Lower interest rates → capital outflows → currency depreciation → cheaper exports and more expensive imports → increased net exports', 'Lower interest rates → capital inflows → currency appreciation → decreased net exports', 'Lower interest rates → no effect on exchange rates → no effect on net exports', 'Lower interest rates → higher imports due to increased domestic spending → improved net exports'], 0, 'Expansionary monetary policy lowers domestic interest rates, making domestic assets less attractive to foreign investors. Capital flows out seeking higher returns elsewhere, increasing the supply of domestic currency in foreign exchange markets. The currency depreciates, making exports cheaper and imports more expensive, increasing net exports. This exchange rate channel reinforces the domestic stimulus.'),
        q(89, 'A country runs a persistent current account surplus. Which of the following must be true about its capital (financial) account and what are the implications?', ['Its financial account must also show a surplus.', 'It must have a financial account deficit, meaning it is a net lender/investor abroad, accumulating foreign assets.', 'Its financial account is unrelated to the current account.', 'It must have zero balance in its financial account.'], 1, 'The balance of payments identity requires the current account and financial account to sum to approximately zero. A current account surplus means the country exports more than it imports, earning more foreign currency than it spends. This excess is invested abroad (financial account deficit/capital outflow), making the country a net creditor—acquiring foreign assets like bonds, stocks, and real estate.'),
        q(90, 'A developing country pegs its currency to the U.S. dollar but experiences higher inflation than the U.S. Which unsustainable dynamic does this create?', ['The peg automatically adjusts for inflation differences.', 'The country\'s goods become increasingly overpriced relative to U.S. goods (the real exchange rate appreciates), worsening the trade balance, draining foreign reserves used to maintain the peg, and eventually forcing a painful devaluation or abandonment of the peg.', 'The higher inflation automatically reduces the country\'s imports.', 'The peg causes U.S. inflation to increase to match.'], 1, 'With a fixed nominal exchange rate but higher domestic inflation, the country\'s real exchange rate appreciates—its goods become progressively more expensive relative to the U.S. This reduces exports, increases imports, and creates a current account deficit. Maintaining the peg requires the central bank to sell foreign reserves to buy its own currency, depleting reserves. Eventually, reserves are exhausted and the peg collapses, often resulting in a sharp, disorderly devaluation.'),
      ],
    },
  ],
}
